// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/
// color palette from https://iquilezles.org/www/articles/palettes/palettes.htm

let theShader;

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
	let s = max(windowWidth, windowHeight);
	createCanvas(s, s, WEBGL);
	noStroke();
}

function draw() {
	shader(theShader);
	theShader.setUniform('u_resolution', [2, 1]);
	theShader.setUniform('u_time', millis()/1000);

	rect(0, 0, width, height);
}

// === Tab: frag ===
const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	varying vec2 vTexCoord;

	uniform vec2 u_resolution;
	//uniform vec2 u_mouse;
	uniform float u_time;

	void main() {
		vec2 st = vTexCoord.xy/u_resolution.xy;
		st.x *= u_resolution.x/u_resolution.y;

		float v = sqrt(0.25-pow(st.y-0.5, 2.));
    float x1 = 0.5-v, x2 = 0.5+v;
    float t = clamp((st.x-x1)/(x2-x1), 0., 1.) + u_time;

		//if (length(vec2(st.x-0.5, st.y-0.5)) > 0.5) t = 0.5+u_time;
		if (st.y > 0.5) t = t + 0.5;

		vec3 a = vec3(0.5, 0.5, 0.5);
		vec3 b = vec3(0.5, 0.5, 0.5);
		vec3 c = vec3(1.0, 1.0, 1.0);
		vec3 d = vec3(0.00, 0.10, 0.20);
		vec3 color = a+b*cos(6.28318530718*(c*t+d));

		gl_FragColor = vec4(color,1.0);
	}
`;

// === Tab: vert ===
const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;

		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

